 * the pale panel the site's interface mockups sit in, filled edge to edge.
 */
declare function WorkflowMedia({ variant, children, className }: {
    variant?: "story" | "mockup";
    children?: React.ReactNode;
    className?: string;
}): React.JSX.Element;
declare function WorkflowCard({ title, description, media, mediaVariant, className }: WorkflowItem & {
    className?: string;
}): React.JSX.Element;
declare function WorkflowGrid({ items, className }: {
    items: WorkflowItem[];
    className?: string;
}): React.JSX.Element;
